import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Handl SDK Generator — Bukkit, Spigot, Paper Backend","description":"","frontmatter":{"title":"Handl SDK Generator — Bukkit, Spigot, Paper Backend","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"proposed","status_note":"Proposed."},"headers":[],"relativePath":"c/project/adrs/0112-handl-sdkgen-bukkit-spigot-paper.md","filePath":"vendored/c/project/adrs/0112-handl-sdkgen-bukkit-spigot-paper.md"}`),a={name:`c/project/adrs/0112-handl-sdkgen-bukkit-spigot-paper.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0112-handl-sdk-generator-—-bukkit-spigot-paper-backend" tabindex="-1">ADR-0112: Handl SDK Generator — Bukkit, Spigot, Paper Backend <a class="header-anchor" href="#adr-0112-handl-sdk-generator-—-bukkit-spigot-paper-backend" aria-label="Permalink to “ADR-0112: Handl SDK Generator — Bukkit, Spigot, Paper Backend”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a> established a backend-agnostic <code>SdkgenModule</code> IR, and <a href="./0111-handl-sdkgen-jvm.html">ADR-0111</a> proposes a generic JVM backend. Bukkit, Spigot, Paper, and similar Minecraft server platforms are large Java APIs. They should be supported as a specialized JVM backend rather than as a separate language target.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Build <code>plugin-sdkgen-backend-bukkit</code> on top of the JVM backend (<code>plugin-sdkgen-backend-jvm</code>).</p><ul><li>The Bukkit backend accepts a manifest of Bukkit / Spigot / Paper class mappings (e.g. <code>org.bukkit.Server</code>, <code>org.bukkit.entity.Player</code>) and emits Handl ports and adapters for them.</li><li>It reuses the JVM IR and the <code>jvm</code> client package.</li><li>It adds event-hook generation so Bukkit events can be exposed as Handl graded arrows.</li><li>A <code>.sdkgen.yaml</code> file selects the target platform (<code>bukkit</code> / <code>spigot</code> / <code>paper</code>) and version so the correct class names and method signatures are used.</li><li>The first target is Spigot / Paper on Linux x86_64 because that is the most common server stack. Windows / macOS server support is out of scope.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Handl can author Minecraft server plugins in Handl while reusing the full Bukkit / Spigot / Paper API.</li><li>The JVM backend (ADR-0111) is a hard prerequisite.</li><li>Configuration (<code>.sdkgen.yaml</code>) becomes more important because the class inventory is large and versioned.</li><li>This work has lower priority than the generic JVM backend but higher priority than Windows / macOS C support (ADR-0110).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a></li><li><a href="./0111-handl-sdkgen-jvm.html">ADR-0111 — Handl SDK Generator: JVM Backend</a></li><li><code>crates/plugin-sdkgen</code></li></ul>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};